import {setBlockGeometry} from './building-block-geometry.js?v=theme-park-1';
import {validateSurfaceDetails} from './building-surface-details.js?v=theme-park-1';
import {validateFloorPaint,clearColumnFloorPaint} from './building-floor-paint.js?v=theme-park-1';
import {validateBuildingMaterials} from './building-materials.js?v=theme-park-1';
import {BUILDING_EDIT_PLANES,voxelPlanePoint,voxelPlaneCells,paintVoxelPlane,paintVoxelCells} from './building-edit-planes.js?v=theme-park-1';
import {voxelStatistics} from './building-voxels.js?v=theme-park-1';
import {buildingShapeCells} from './building-shapes.js?v=theme-park-1';
export function mountBuildingVoxelEditor(root,{get,set,view=()=>{}}){
 root.innerHTML=`<section id="voxelWorkspace" hidden><p>Edit a horizontal floor or a vertical cross-section. Vertical views show layer 24 at the top and layer 1 at the bottom. The model guide is green for floors, red for west–east slices and blue for north–south slices; yellow previews the pending edit. Blocks above an erased space stay in place, allowing arches and overhangs. Switching construction methods keeps separate drafts until you choose another building style.</p><div class="block-editor-controls"><label>Edit plane<select id="voxelPlane"><option value="horizontal">Horizontal floor</option><option value="xz">Vertical west–east</option><option value="yz">Vertical north–south</option></select></label><label><span id="voxelPositionLabel">Floor layer (1–24)</span><input id="voxelLevel" type="number" min="1" max="24" step="1" value="1"></label><label>Move edit plane<input id="voxelPlaneSlider" type="range" min="1" max="24" step="1" value="1"></label><button id="voxelPrevious">Previous slice</button><button id="voxelNext">Next slice</button><label>Action<select id="voxelAction"><option value="place">Place blocks</option><option value="erase">Erase blocks</option></select></label><label>Block geometry<select id="voxelGeometry"><option value="0">Cube</option><option value="1">Wedge · rises north</option><option value="2">Wedge · rises east</option><option value="3">Wedge · rises south</option><option value="4">Wedge · rises west</option></select></label><label>Application<select id="voxelShape"><option value="single">Freehand blocks</option><option value="line">Line</option><option value="plane">Plane</option></select></label><button id="voxelUndo">Undo layered edit</button><button id="voxelRedo">Redo layered edit</button></div><div id="voxelGrid" role="grid" aria-label="Building layer, north at top" aria-rowcount="10" aria-colcount="10">${Array.from({length:10},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-voxel-index="${y*10+x}" tabindex="${x===0&&y===0?0:-1}"></button>`).join('')}</div>`).join('')}</div><p>Filled square: cube. Triangle: wedge rising in the indicated world direction. Wedges keep their orientation when you rotate the preview. Sloped roofs accept surface paint and vent details; wall textures and details are clipped to triangular faces. Dot: empty here. Outline: placement preview. Move through slices with the slider, Previous/Next, the wheel over this grid or Page Up/Down. Moving a slice cancels a pending stroke. Freehand follows your drag, including turns; Line and Plane connect their endpoints. Release to place; Shift on release or Escape cancels. Keyboard: Shift+Enter starts, arrows extend, Enter places. Paint individual floor surfaces directly on the model preview. Paint stays at its floor position when blocks are edited.</p><p id="voxelStatus" role="status"></p></section>`;
 const $=id=>root.querySelector('#'+id),grid=$('voxelGrid'),undo=[],redo=[];let cells=[...grid.querySelectorAll('[data-voxel-index]')],active=0,pending=null,pointer=null,wheelDelta=0,wheelTime=0;
 const plane=()=>$('voxelPlane').value||'horizontal';
 const level=()=>Number($('voxelLevel').value)-1,snapshot=()=>({blockGeometry:get().blockGeometry,voxels:[...get().voxels],surfaceDetails:get().surfaceDetails,surfacePaint:get().surfacePaint,materials:get().materials?[...get().materials]:undefined});
 function refresh(){const voxels=get().voxels;$('voxelWorkspace').hidden=!voxels;if(!voxels){view();return;}const p=BUILDING_EDIT_PLANES[plane()],z=level();$('voxelPositionLabel').textContent=p.position;$('voxelLevel').max=p.slices;$('voxelPlaneSlider').max=p.slices;$('voxelPlaneSlider').value=String(Math.min(p.slices,Math.max(1,z+1||1)));$('voxelPlaneSlider').setAttribute('aria-valuetext',`${p.position.split(' (')[0]} ${z+1} of ${p.slices}`);$('voxelPrevious').disabled=z<=0;$('voxelNext').disabled=z>=p.slices-1;if(!Number.isInteger(z)||z<0||z>=p.slices){$('voxelStatus').textContent=`Choose a whole position from 1 to ${p.slices}.`;view();return;}if(cells.length!==p.rows*10){grid.innerHTML=Array.from({length:p.rows},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-voxel-index="${y*10+x}" tabindex="-1"></button>`).join('')}</div>`).join('');cells=[...grid.querySelectorAll('[data-voxel-index]')];active=Math.min(active,cells.length-1);}grid.setAttribute('aria-rowcount',String(p.rows));grid.setAttribute('aria-label',p.label+' building cross-section');grid.dataset.vertical=String(p.rows===24);const layer=voxelPlaneCells(voxels,plane(),z),marked=pending?new Set(pending.cells||buildingShapeCells(pending.kind,pending.start,pending.end,p.rows)):new Set();cells.forEach((cell,i)=>{const shape=Number(get().blockGeometry?.[layer[i].z*100+layer[i].y*10+layer[i].x]||0);cell.textContent=layer[i].occupied?shape?['','▲','▶','▼','◀'][shape]:'■':'·';cell.tabIndex=i===active?0:-1;cell.setAttribute('aria-label',`Column ${layer[i].x+1}, row ${layer[i].y+1}, layer ${layer[i].z+1}: ${layer[i].occupied?shape?'occupied wedge rising '+['','north','east','south','west'][shape]:'occupied':'empty'}`);cell.style.background=layer[i].occupied?'#608f88':'#eef1ef';cell.style.color=layer[i].occupied?'#fff':'#17382f';cell.style.boxShadow=marked.has(i)?'inset 0 0 0 3px #d79b00':'';});$('voxelUndo').disabled=!undo.length;$('voxelRedo').disabled=!redo.length;const stats=voxelStatistics(voxels);$('voxelStatus').textContent=`${stats.count} blocks · ${stats.columns} occupied columns · highest layer ${stats.height}. Draft until applied.`;view();}
 function cancel(){pending=null;pointer=null;refresh();}
 function moveSlice(value){const maximum=BUILDING_EDIT_PLANES[plane()].slices;$('voxelLevel').value=String(Math.min(maximum,Math.max(1,Math.round(value)||1)));cancel();}
 $('voxelPlaneSlider').oninput=()=>moveSlice(Number($('voxelPlaneSlider').value));$('voxelPrevious').onclick=()=>moveSlice(level());$('voxelNext').onclick=()=>moveSlice(level()+2);
 function begin(i){const z=level();if(!Number.isInteger(z)||z<0||z>=BUILDING_EDIT_PLANES[plane()].slices){refresh();return;}pending={start:i,end:i,level:z,plane:plane(),kind:$('voxelShape').value==='plane'?'plane':'line',...($('voxelShape').value==='single'?{cells:[i]}:{}),geometry:Number($('voxelGeometry').value)||0,place:$('voxelAction').value==='place'};refresh();}
 function extend(i){if(pending.cells)pending.cells=[...new Set([...pending.cells,...buildingShapeCells('line',pending.end,i,BUILDING_EDIT_PLANES[pending.plane].rows)])];pending.end=i;}
 function commit(cancelled=false){const p=pending;pending=null;pointer=null;if(p&&!cancelled){const next=p.cells?paintVoxelCells(get().voxels,p.plane,p.level,p.cells,p.place):paintVoxelPlane(get().voxels,p.plane,p.level,p.kind,p.start,p.end,p.place);const points=(p.cells||buildingShapeCells(p.kind,p.start,p.end,BUILDING_EDIT_PLANES[p.plane].rows)).map(i=>voxelPlanePoint(p.plane,p.level,i)),geometry=setBlockGeometry(get().blockGeometry,points,p.place?p.geometry:0,next);if(next.some((v,i)=>v!==get().voxels[i])||geometry!==get().blockGeometry){undo.push(snapshot());if(undo.length>20)undo.shift();redo.length=0;set({...get(),voxels:next,blockGeometry:geometry});}}refresh();}
 $('voxelUndo').onclick=()=>{cancel();if(undo.length){redo.push(snapshot());set({...get(),...undo.pop()});refresh();}};$('voxelRedo').onclick=()=>{cancel();if(redo.length){undo.push(snapshot());set({...get(),...redo.pop()});refresh();}};
 for(const id of ['voxelLevel','voxelAction','voxelShape','voxelGeometry'])$(id).onchange=cancel;$('voxelLevel').oninput=cancel;$('voxelPlane').onchange=()=>{$('voxelLevel').value=String(Math.min(Math.max(1,Number($('voxelLevel').value)||1),BUILDING_EDIT_PLANES[plane()].slices));cancel();};
 grid.onpointerdown=e=>{if(e.button!==0)return;const cell=e.target.closest('[data-voxel-index]');if(!cell)return;e.preventDefault();active=Number(cell.dataset.voxelIndex);cell.focus({preventScroll:true});pointer=e.pointerId;grid.setPointerCapture(pointer);begin(active);};
 grid.onpointermove=e=>{if(e.pointerId!==pointer||!pending)return;const cell=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-voxel-index]');if(cell&&grid.contains(cell)){extend(Number(cell.dataset.voxelIndex));refresh();}};
 grid.onpointerup=e=>{if(e.pointerId===pointer)commit(e.shiftKey);};grid.onpointercancel=cancel;
 grid.onclick=e=>{if(e.detail!==0)return;const cell=e.target.closest('[data-voxel-index]');if(cell){active=Number(cell.dataset.voxelIndex);begin(active);commit();}};
 grid.onwheel=e=>{if(e.ctrlKey||e.metaKey||!e.deltaY)return;const time=e.timeStamp||0;if(time-wheelTime>180)wheelDelta=0;wheelTime=time;wheelDelta+=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?120:1);e.preventDefault();const steps=Math.trunc(wheelDelta/60);if(steps){wheelDelta-=steps*60;moveSlice(level()+1-steps);}};
 grid.onkeydown=e=>{if(e.key==='PageUp'||e.key==='PageDown'){e.preventDefault();moveSlice(level()+1+(e.key==='PageUp'?1:-1));return;}if(e.key==='Escape'&&pending){e.preventDefault();cancel();return;}if(e.key==='Enter'&&(e.shiftKey||pending)){e.preventDefault();if(pending)commit();else begin(active);return;}const moves={ArrowLeft:-1,ArrowRight:1,ArrowUp:-10,ArrowDown:10};if(!(e.key in moves))return;e.preventDefault();const cell=e.target.closest('[data-voxel-index]');if(cell)active=Number(cell.dataset.voxelIndex);const next=active+moves[e.key];if(next<0||next>=cells.length||e.key==='ArrowLeft'&&active%10===0||e.key==='ArrowRight'&&active%10===9)return;active=next;if(pending)extend(active);refresh();cells[active].focus();};
 return{applyDetails(details){const next=validateSurfaceDetails(details);if(!get().voxels||next===get().surfaceDetails)return;undo.push(snapshot());if(undo.length>20)undo.shift();redo.length=0;set({...get(),surfaceDetails:next});refresh();},applyFloorPaint(paint){const next=validateFloorPaint(paint);if(!get().voxels||next===get().surfacePaint)return;undo.push(snapshot());if(undo.length>20)undo.shift();redo.length=0;set({...get(),surfacePaint:next});refresh();},applyMaterials(materials){const next=validateBuildingMaterials(materials);if(!get().voxels)return;if(next.every((v,i)=>v===(get().materials?.[i]||0)))return;undo.push(snapshot());if(undo.length>20)undo.shift();redo.length=0;set({...get(),materials:next,surfacePaint:clearColumnFloorPaint(get().surfacePaint,next.map((v,i)=>i).filter(i=>next[i]!==(get().materials?.[i]||0)))});refresh();},selection(){const slice=level(),p=BUILDING_EDIT_PLANES[plane()];return get().voxels&&p&&Number.isInteger(slice)&&slice>=0&&slice<p.slices?{plane:plane(),slice,pending:pending?{kind:pending.kind,start:pending.start,end:pending.end,...(pending.cells?{cells:[...pending.cells]}:{})}:null}:null;},refresh,reset(){undo.length=0;redo.length=0;pending=null;pointer=null;refresh();}};
}
